  - id: q1
    prompt: "What is the type of a catch variable under strict mode?"
    type: single
    choices: ["Error", "unknown", "any", "never"]
    answer: [1]
    explanation: "Anything can be thrown, so the caught value is unknown."
    difficulty: 1
